import type pg from 'pg';
import { withSystemContext, type Tx } from './pool.ts';

const SCHEMA = /^[a-z][a-z0-9_]{1,40}$/;
const q = (schema: string): string => {
  if (!SCHEMA.test(schema)) throw new Error(`invalid schema name "${schema}"`);
  return `"${schema}"`;
};

/**
 * Tables every service owns for reliable messaging and accountability (ADR-010/015). This SQL is the single
 * source of truth: services apply it as their first migration (`0000_common_tables.sql`, generated by
 * `scripts/gen-common-migration.ts`), so every schema is identical and tested once.
 */
export function commonTablesSql(schema: string): string {
  const s = q(schema);
  return `-- Common tables (generated from @saudaro/database-utils commonTablesSql)
CREATE TABLE ${s}.outbox_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type text NOT NULL,
  payload jsonb NOT NULL,
  headers jsonb NOT NULL DEFAULT '{}'::jsonb,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','published','dead')),
  attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  next_attempt_at timestamptz NOT NULL DEFAULT now(),
  last_error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz
);--> statement-breakpoint
CREATE INDEX ix_outbox_pending ON ${s}.outbox_events (next_attempt_at, created_at) WHERE status = 'pending';--> statement-breakpoint
CREATE TABLE ${s}.inbox_events (
  consumer text NOT NULL,
  event_id uuid NOT NULL,
  event_type text NOT NULL,
  received_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (consumer, event_id)
);--> statement-breakpoint
CREATE TABLE ${s}.audit_log (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  actor_type text NOT NULL CHECK (actor_type IN ('user','admin','system','service')),
  actor_user_id uuid,
  company_id uuid,
  action text NOT NULL,
  resource_type text NOT NULL,
  resource_id uuid,
  request_id text,
  ip_address inet,
  changes jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);--> statement-breakpoint
CREATE INDEX ix_audit_log_company_time ON ${s}.audit_log (company_id, created_at DESC);--> statement-breakpoint
CREATE INDEX ix_audit_log_resource ON ${s}.audit_log (resource_type, resource_id, created_at DESC);--> statement-breakpoint
CREATE FUNCTION ${s}.forbid_modification() RETURNS trigger LANGUAGE plpgsql AS $fn$
BEGIN
  RAISE EXCEPTION '% is append-only (% rejected)', TG_TABLE_NAME, TG_OP USING ERRCODE = '42501';
END $fn$;--> statement-breakpoint
CREATE TRIGGER trg_audit_log_append_only BEFORE UPDATE OR DELETE ON ${s}.audit_log
  FOR EACH ROW EXECUTE FUNCTION ${s}.forbid_modification();--> statement-breakpoint
CREATE TRIGGER trg_audit_log_no_truncate BEFORE TRUNCATE ON ${s}.audit_log
  FOR EACH STATEMENT EXECUTE FUNCTION ${s}.forbid_modification();
`;
}

// ---- transactional outbox -------------------------------------------------------------------------------
export interface OutboxEvent {
  aggregateType: string;
  aggregateId: string;
  eventType: string;
  payload: unknown;
  headers?: Record<string, string>;
}

/** Call INSIDE the business transaction: the event is committed atomically with the state change. */
export async function enqueueEvent(tx: Tx, schema: string, event: OutboxEvent): Promise<string> {
  const r = await tx.query<{ id: string }>(
    `INSERT INTO ${q(schema)}.outbox_events (aggregate_type, aggregate_id, event_type, payload, headers)
     VALUES ($1, $2, $3, $4::jsonb, $5::jsonb) RETURNING id`,
    [
      event.aggregateType,
      event.aggregateId,
      event.eventType,
      JSON.stringify(event.payload),
      JSON.stringify(event.headers ?? {}),
    ],
  );
  return r.rows[0]!.id;
}

/** Exponential backoff with FULL jitter: random in [0, min(max, base * 2^attempt)]. */
export function backoffMs(
  attempt: number,
  o: { baseMs?: number; maxMs?: number } = {},
  random: () => number = Math.random,
): number {
  const cap = Math.min(o.maxMs ?? 60_000, (o.baseMs ?? 500) * 2 ** Math.max(0, attempt));
  return Math.floor(random() * cap);
}

export interface RelayOptions {
  batchSize?: number;
  maxAttempts?: number;
  baseMs?: number;
  maxMs?: number;
  random?: () => number;
}

export interface PublishedEvent {
  id: string;
  aggregateType: string;
  aggregateId: string;
  eventType: string;
  payload: unknown;
  headers: Record<string, string>;
  createdAt: Date;
}

/**
 * One relay pass: claims due rows with FOR UPDATE SKIP LOCKED (safe with many replicas), publishes each,
 * marks it published, or reschedules with backoff, or parks it as `dead` after `maxAttempts` (dead-letter).
 * Returns counts for metrics. Delivery is AT-LEAST-ONCE: consumers must be idempotent (see consumeOnce).
 */
export async function relayOutbox(
  pool: pg.Pool,
  schema: string,
  publish: (event: PublishedEvent) => Promise<void>,
  opts: RelayOptions = {},
): Promise<{ published: number; retried: number; dead: number }> {
  const maxAttempts = opts.maxAttempts ?? 8;
  const counts = { published: 0, retried: 0, dead: 0 };
  await withSystemContext(pool, async (tx) => {
    const due = await tx.query(
      `SELECT id, aggregate_type, aggregate_id, event_type, payload, headers, attempts, created_at
       FROM ${q(schema)}.outbox_events
       WHERE status = 'pending' AND next_attempt_at <= now()
       ORDER BY created_at LIMIT $1 FOR UPDATE SKIP LOCKED`,
      [opts.batchSize ?? 50],
    );
    for (const row of due.rows) {
      try {
        await publish({
          id: row.id,
          aggregateType: row.aggregate_type,
          aggregateId: row.aggregate_id,
          eventType: row.event_type,
          payload: row.payload,
          headers: row.headers,
          createdAt: row.created_at,
        });
        await tx.query(
          `UPDATE ${q(schema)}.outbox_events SET status = 'published', published_at = now() WHERE id = $1`,
          [row.id],
        );
        counts.published += 1;
      } catch (err) {
        const attempts = row.attempts + 1;
        const message = String((err as Error)?.message ?? err).slice(0, 500);
        if (attempts >= maxAttempts) {
          await tx.query(
            `UPDATE ${q(schema)}.outbox_events SET status = 'dead', attempts = $2, last_error = $3 WHERE id = $1`,
            [row.id, attempts, message],
          );
          counts.dead += 1;
        } else {
          const delay = backoffMs(attempts, opts, opts.random);
          await tx.query(
            `UPDATE ${q(schema)}.outbox_events
             SET attempts = $2, last_error = $3, next_attempt_at = now() + ($4 || ' milliseconds')::interval WHERE id = $1`,
            [row.id, attempts, message, String(delay)],
          );
          counts.retried += 1;
        }
      }
    }
  });
  return counts;
}

// ---- idempotent consumer --------------------------------------------------------------------------------
/**
 * Runs `handler` at most once per (consumer, eventId): the inbox row and the handler's writes commit in ONE
 * transaction, so a crash re-delivers the event and a duplicate delivery is a no-op.
 */
export async function consumeOnce(
  pool: pg.Pool,
  schema: string,
  consumer: string,
  event: { id: string; type: string },
  handler: (tx: Tx) => Promise<void>,
): Promise<'processed' | 'duplicate'> {
  return withSystemContext(pool, async (tx) => {
    const ins = await tx.query(
      `INSERT INTO ${q(schema)}.inbox_events (consumer, event_id, event_type) VALUES ($1, $2, $3)
       ON CONFLICT DO NOTHING`,
      [consumer, event.id, event.type],
    );
    if (ins.rowCount === 0) return 'duplicate' as const;
    await handler(tx);
    return 'processed' as const;
  });
}
